import type { Prayer } from "./prayerCategories";

export const NOVENA_PRAYERS_15: Prayer[] = [

  // NOVENA TO SAINT ANNE — Patroness of Mothers and Grandmothers
  // novenaId: "novenas-saint-anne"

  {
    id: "sa-np-1",
    novenaId: "novenas-saint-anne",
    title: "Day 1 — Motherhood: The Sacred Calling",
    category: "novenas",
    day: 1,
    intention: "To honor and embrace the sacred vocation of motherhood",
    text: `O glorious Saint Anne, mother of the Blessed Virgin Mary and grandmother of our Lord Jesus Christ, you were chosen by God for the most exalted maternity in human history after that of Eve. You who bore in your womb her who would bear the Savior of the world, intercede for all mothers today. Grant that every mother may understand the sacred dignity of her calling, that she carries within her not merely flesh but immortal souls destined for eternity. Help mothers to see in their daily labors of feeding, clothing, teaching, and nurturing their children a participation in the very creative love of God. When motherhood feels overwhelming, when the nights are long and the burdens heavy, remind them that God has entrusted them with souls of infinite worth. O Saint Anne, mother of Mary, obtain for all mothers the grace to embrace their vocation with joy, patience, and unwavering faith.`,
  },
  {
    id: "sa-np-2",
    novenaId: "novenas-saint-anne",
    title: "Day 2 — Family: The Domestic Church",
    category: "novenas",
    day: 2,
    intention: "To strengthen the bonds of Christian family life",
    text: `O blessed Saint Anne, you presided over a household that became the first Christian home, the domestic church in which the Word of God took flesh and dwelt among us. You and your husband Saint Joachim created a home ordered by faith, love, and devotion to God — a home worthy of being the dwelling place of the Immaculate Virgin. Teach me to build my own family upon the rock of prayer and mutual charity. Help me to create in my home an atmosphere of warmth, forgiveness, and holiness where God is honored and each member is cherished. When conflicts arise and misunderstandings divide, remind me that the family that prays together stays together. O Saint Anne, model of Christian family life, intercede that every home may become a sanctuary of love and faith.`,
  },
  {
    id: "sa-np-3",
    novenaId: "novenas-saint-anne",
    title: "Day 3 — Education: Forming Souls for Eternity",
    category: "novenas",
    day: 3,
    intention: "To faithfully educate children in faith and virtue",
    text: `O wise Saint Anne, you were entrusted with the education of the most perfect creature ever born of woman — the Blessed Virgin Mary. You taught her the Scriptures, the prayers, and the traditions of Israel, preparing her to receive the angel Gabriel's announcement with humble faith. Grant me the wisdom and patience to educate the children under my care in the ways of faith, virtue, and holy living. Help me to see education not merely as the transmission of knowledge but as the formation of souls. Give me the grace to teach by example, to show through my own life what it means to love God and neighbor. May the seeds of faith I plant in young hearts bear fruit for eternal life. O Saint Anne, patroness of educators, obtain for me the gift of forming disciples of Christ.`,
  },
  {
    id: "sa-np-4",
    novenaId: "novenas-saint-anne",
    title: "Day 4 — Patience: The Quiet Virtue",
    category: "novenas",
    day: 4,
    intention: "To grow in patience through trials and waiting",
    text: `O patient Saint Anne, for many years you and Saint Joachim prayed for a child, enduring the sorrow and social shame of barrenness in a culture that valued fertility. You waited twenty years before God answered your prayer with the gift of Mary. In that long waiting, you learned the deep virtue of patience — the quiet endurance of hope that trusts in God's timing. I bring before you my own struggles with impatience: my frustration when answers to prayer seem delayed, my irritation when circumstances do not conform to my plans, my anxiety when life moves slower than I wish. Teach me that God's delays are not God's denials, that He is working all things together for good in His perfect wisdom. O Saint Anne, patroness of the patient, obtain for me the grace to trust in God's providential timing.`,
  },
  {
    id: "sa-np-5",
    novenaId: "novenas-saint-anne",
    title: "Day 5 — Faith: Trusting in God's Promise",
    category: "novenas",
    day: 5,
    intention: "To deepen trust in God's faithfulness",
    text: `O faithful Saint Anne, you believed the promise of God even when all visible evidence seemed to contradict it. The angel who appeared to you in the garden announced that you would conceive a daughter, and you believed without hesitation. Your faith was rewarded beyond all imagining — you became the grandmother of the Messiah. Strengthen my faith today, O Saint Anne. When doubts assail me, when the darkness of uncertainty surrounds me, when I cannot see God's hand at work in my life, help me to cling to His promises as you did. Grant me the faith that moves mountains, the faith that trusts even when I cannot understand, the faith that believes God is always good and always faithful. O Saint Anne, woman of great faith, obtain for me an unshakeable trust in the word of the Lord.`,
  },
  {
    id: "sa-np-6",
    novenaId: "novenas-saint-anne",
    title: "Day 6 — Grandmotherhood: The Blessing of Generations",
    category: "novenas",
    day: 6,
    intention: "To cherish and fulfill the role of grandparent",
    text: `O blessed Saint Anne, you hold the unique honor of being the grandmother of Jesus Christ, the Savior of the world. Through your daughter Mary, you were given the sacred privilege of holding in your arms the incarnate Son of God. You represent all grandmothers who pass down the faith from generation to generation. Bless all grandparents today, O Saint Anne. Help them to see their role not as diminished with age but as elevated — for grandparents are the living memory of faith, the keepers of family stories, the bridges between past and future. Grant grandparents the health, joy, and spiritual strength to be witnesses of God's faithfulness to their grandchildren. O Saint Anne, grandmother of the Savior, obtain for all grandparents the grace to transmit the faith with love and wisdom.`,
  },
  {
    id: "sa-np-7",
    novenaId: "novenas-saint-anne",
    title: "Day 7 — Intercession: A Powerful Advocate",
    category: "novenas",
    day: 7,
    intention: "To trust in Saint Anne's intercession before God",
    text: `O powerful Saint Anne, the Church has long recognized your special ability to intercede before the throne of God on behalf of those who honor you. Your unique position — as mother of the Immaculate Virgin and grandmother of the Savior — gives you a place of extraordinary honor among the saints. I come before you today with confidence, knowing that you never turn away a soul who seeks your help. Present my petitions before God with the same love with which you presented the infant Mary at the Temple. I ask you to pray for my specific needs, for the intentions I carry in my heart, and for those I love. When I am too weak to pray for myself, pray for me. When I do not know what to ask, ask God for what I need. O Saint Anne, powerful intercessor, I place my trust in your heavenly advocacy.`,
  },
  {
    id: "sa-np-8",
    novenaId: "novenas-saint-anne",
    title: "Day 8 — Healing: Body, Soul, and Spirit",
    category: "novenas",
    day: 8,
    intention: "To receive healing through Saint Anne's intercession",
    text: `O compassionate Saint Anne, you who experienced the healing of barrenness through God's miraculous power, understand deeply the suffering of those who are ill in body, mind, or spirit. You know the longing for wholeness, the ache of affliction, and the joy of restoration. I bring before you today all who are suffering from illness of any kind. Heal the sick through your powerful intercession, O Saint Anne. Restore health to the diseased, comfort to the afflicted, peace to the troubled, and strength to the weak. I especially ask for healing in my own body, for the removal of any illness that diminishes my ability to serve God and neighbor. Trusting in your compassion, I ask you to present my plea for healing before the throne of God. O Saint Anne, patroness of the suffering, obtain for me the grace of complete healing according to God's holy will.`,
  },
  {
    id: "sa-np-9",
    novenaId: "novenas-saint-anne",
    title: "Day 9 — Thanksgiving: Gratitude for God's Gifts",
    category: "novenas",
    day: 9,
    intention: "To cultivate a heart of gratitude for God's blessings",
    text: `O thankworthy Saint Anne, as this novena draws to a close, I desire to offer thanksgiving to God for the countless blessings He has bestowed upon me through your intercession. You who received the gift of Mary with such gratitude teach me to receive every gift of God with the same spirit of thanksgiving. For the gift of life, I thank God. For the gift of faith, I thank God. For the gift of family and friends, for the Sacraments, for the Church, for every breath and heartbeat — all is gift. Help me to cultivate a heart that is always grateful, a spirit that counts blessings rather than complaints, a soul that recognizes the hand of God in every circumstance. O Saint Anne, mother blessed of God, obtain for me the grace to live each day in joyful gratitude for God's infinite goodness and mercy.`,
  },

  // NOVENA TO SAINT CELESTINE V — The Pope Who Resigned
  // novenaId: "novenas-saint-celestine"

  {
    id: "sc-np-1",
    novenaId: "novenas-saint-celestine",
    title: "Day 1 — Humility: The Foundation of Sanctity",
    category: "novenas",
    day: 1,
    intention: "To cultivate deep humility before God and neighbor",
    text: `O blessed Saint Celestine V, you who were chosen by God to occupy the Chair of Saint Peter yet recognized your own insufficiency for so great a responsibility, teach me the virtue of humility. You understood that true greatness lies not in the exercise of power but in the humble submission to God's will. In a world that exalts pride, ambition, and self-promotion, remind me that Christ Himself washes the feet of His disciples and commands us to do likewise. Help me to decrease that God may increase in my life, to diminish my own ego that His glory may shine through my weakness. Grant me the humility of heart that recognizes my nothingness before the infinite majesty of God. O Saint Celestine, humble successor of Peter, obtain for me a heart that is lowly and contrite, which God will not despise.`,
  },
  {
    id: "sc-np-2",
    novenaId: "novenas-saint-celestine",
    title: "Day 2 — Simplicity: The Way of the Gospel",
    category: "novenas",
    day: 2,
    intention: "To embrace a life of evangelical simplicity",
    text: `O simple-hearted Saint Celestine, you lived as a hermit in the mountains of Abruzzi, clothed in rough garments, eating only the barest sustenance, finding in poverty and simplicity a profound closeness to God. When you were elected Pope, you sought to continue this simple way of life even amid the splendors of the papal court. Teach me to value the things of heaven above the things of earth, to find joy not in possessions or status but in the presence of God. Strip from my heart all attachment to worldly comforts that chains my soul. Grant me the freedom that comes from detachment, the peace that flows from simplicity, the contentment that grows from trusting in divine providence alone. O Saint Celestine, lover of holy poverty, obtain for me a spirit of evangelical simplicity.`,
  },
  {
    id: "sc-np-3",
    novenaId: "novenas-saint-celestine",
    title: "Day 3 — Prayer: The Breath of the Soul",
    category: "novenas",
    day: 3,
    intention: "To grow in the life of deep and continuous prayer",
    text: `O contemplative Saint Celestine, your life was one of unceasing prayer. In the solitude of your mountain cave, you spent hours in communion with God, lifting your heart to Him in adoration, supplication, and praise. You understood that prayer is not merely a duty but the very breath of the soul, the means by which the creature communicates with the Creator. I pray today that the spirit of prayer may take deeper root in my soul. Help me to pray not only in times of need but in moments of abundance, not only in church but in every place and every circumstance of life. Teach me to listen for the voice of God in the silence of my heart, to speak to Him as a child speaks to a loving father. O Saint Celestine, man of unceasing prayer, intercede that I may never cease to converse with God throughout the day and night.`,
  },
  {
    id: "sc-np-4",
    novenaId: "novenas-saint-celestine",
    title: "Day 4 — Papal Service: Bearing the Burden of Authority",
    category: "novenas",
    day: 4,
    intention: "To pray for and support the Holy Father",
    text: `O Saint Celestine V, you who were called to bear the immense responsibility of the papacy, you understood the weight of shepherding the universal Church. Though your pontificate was brief, you accepted the call to serve as Vicar of Christ on earth. I pray today for our current Holy Father, asking that God grant him wisdom, courage, and holiness in guiding the Barque of Peter through the storms of our age. Help me to support the Pope with my prayers, my obedience, and my sacrifices. May I never speak lightly of the Successor of Peter but always honor him as the visible head of the Body of Christ. Grant all the faithful a spirit of unity with the Holy See and fidelity to the teaching authority of the Church. O Saint Celestine, who bore the papal burden, obtain for the Church shepherds after God's own heart.`,
  },
  {
    id: "sc-np-5",
    novenaId: "novenas-saint-celestine",
    title: "Day 5 — Renunciation: The Courage to Let Go",
    category: "novenas",
    day: 5,
    intention: "To embrace holy detachment and surrender",
    text: `O courageous Saint Celestine, you performed an act unprecedented in the history of the Church when you resigned the papacy, recognizing that God was calling you to a different form of service. Your renunciation was not an act of cowardice but of profound spiritual discernment — you placed God's will above your own position, His plan above your reputation. Teach me to renounce whatever keeps me bound to ego and self-interest. Give me the courage to let go of attachments, positions, and comforts when God calls me to something greater. Help me to understand that true freedom is found not in clinging but in releasing, not in possessing but in surrendering all things to God. O Saint Celestine, who renounced the highest office in the Church, obtain for me the grace of total surrender to the will of God.`,
  },
  {
    id: "sc-np-6",
    novenaId: "novenas-saint-celestine",
    title: "Day 6 — Solitude: Finding God in Silence",
    category: "novenas",
    day: 6,
    intention: "To seek God in periods of quiet and retreat",
    text: `O solitary Saint Celestine, you loved the silence of the mountains, the stillness of the cave, the quiet of the wilderness. In solitude you found not loneliness but the intimate presence of God, who speaks most clearly when the noise of the world is stilled. I pray today for the grace to seek moments of solitude in my own busy life, to withdraw from the constant clamor of technology and distraction and enter into the interior silence where God dwells. Help me to be comfortable in stillness, to resist the fear of silence, and to discover that God is waiting for me in the quiet of my own heart. Teach me that solitude is not escape but encounter — encounter with the living God who desires to commune with me. O Saint Celestine, lover of solitude, obtain for me the gift of interior silence.`,
  },
  {
    id: "sc-np-7",
    novenaId: "novenas-saint-celestine",
    title: "Day 7 — Obedience: Submitting to God's Will",
    category: "novenas",
    day: 7,
    intention: "To grow in filial obedience to God",
    text: `O obedient Saint Celestine, your entire life was marked by submission to the will of God. You obeyed when He called you from the world to the hermitage. You obeyed when the cardinals elected you to the papacy. And you obeyed when the Holy Spirit revealed that you must resign. In each decision, you placed your own understanding beneath the sovereign will of God. I pray today for the virtue of obedience — not blind compliance but the trusting surrender of a child to a loving Father. Help me to recognize God's voice in the teachings of the Church, in the guidance of my spiritual directors, in the circumstances of daily life. Grant me the humility to submit my own plans to God's providence, trusting that His ways are always higher than my ways. O Saint Celestine, model of obedience, obtain for me a will perfectly aligned with the will of God.`,
  },
  {
    id: "sc-np-8",
    novenaId: "novenas-saint-celestine",
    title: "Day 8 — Wisdom: Discerning the Will of God",
    category: "novenas",
    day: 8,
    intention: "To grow in spiritual wisdom and discernment",
    text: `O wise Saint Celestine, your decision to resign the papacy required extraordinary spiritual discernment. You recognized the difference between human ambition and divine calling, between personal comfort and apostolic necessity. This wisdom was born of years of prayer, study, and contemplation of the things of God. I pray today for the gift of spiritual wisdom, the ability to see events and circumstances not merely with human eyes but through the lens of faith. Help me to discern God's will in the complexities of modern life, to distinguish between what is merely good and what is best, between what the world values and what heaven treasures. Grant me the prudence to make decisions according to God's plan and the courage to follow through even when the path is difficult. O Saint Celestine, prudent servant of God, obtain for me the wisdom that comes from above.`,
  },
  {
    id: "sc-np-9",
    novenaId: "novenas-saint-celestine",
    title: "Day 9 — Freedom: Liberation in Christ",
    category: "novenas",
    day: 9,
    intention: "To experience true freedom through surrender to God",
    text: `O free Saint Celestine, in resigning the papacy you discovered a freedom that the world cannot give — the freedom of one who has no attachment to worldly honor or position. You returned to your simple cell and lived out your final years in peace, free from the burdens of office, free for God alone. I pray today for this kind of interior freedom, the liberation of the soul from the chains of ambition, pride, and self-will. Set me free from the tyranny of others' opinions, from the slavery of disordered desires, from the prison of my own ego. Help me to understand that true freedom is not the ability to do whatever I want but the grace to do what God wills. O Saint Celestine, who found freedom in surrender, obtain for me the glorious liberty of the children of God.`,
  },

  // NOVENA TO SAINT BRENDAN THE NAVIGATOR — Patron of Seafarers
  // novenaId: "novenas-saint-brendan"

  {
    id: "sbr-np-1",
    novenaId: "novenas-saint-brendan",
    title: "Day 1 — Adventure: The Call of the Unknown",
    category: "novenas",
    day: 1,
    intention: "To embrace the冒险 of faith with courage",
    text: `O glorious Saint Brendan, abbot and navigator, you who set sail upon the vast and unknown Atlantic in a small leather boat, seeking the Island of the Blessed, teach me to embrace the adventure of faith. You heard the call of God to go where no one had gone, to trust in His guidance through uncharted waters, and you responded with heroic courage. I pray today that God may awaken in my soul a holy restlessness, a desire to venture beyond the familiar shores of comfort and routine into the deep waters of divine love. Help me to trust that God has prepared a land of promise for those who are willing to set sail. May I never be so attached to safety that I refuse the call of Christ to follow Him into the unknown. O Saint Brendan, navigator of faith, obtain for me the courage to embrace God's adventure for my life.`,
  },
  {
    id: "sbr-np-2",
    novenaId: "novenas-saint-brendan",
    title: "Day 2 — Seafaring: Trusting God in the Storm",
    category: "novenas",
    day: 2,
    intention: "To trust in God's providence amid life's trials",
    text: `O brave Saint Brendan, you faced storms, whirlpools, sea monsters, and endless horizons of open ocean during your seven-year voyage. Yet you never despaired, for you knew that God who called you to sea would also guide you through every tempest. I bring before you today the storms of my own life — the trials that toss me about, the difficulties that seem overwhelming, the moments when I feel lost and alone upon a turbulent sea. Remind me that Jesus Himself calmed the winds and the waves, and that no storm can separate me from His love. Help me to keep my eyes fixed on Christ in every trial, trusting that He is with me in the boat. Grant me the serenity to accept what I cannot change, the courage to navigate through adversity, and the faith to believe that calm waters lie ahead. O Saint Brendan, master of the seas, intercede that I may weather every storm with Christ as my captain.`,
  },
  {
    id: "sbr-np-3",
    novenaId: "novenas-saint-brendan",
    title: "Day 3 — Evangelization: Proclaiming Christ to the Nations",
    category: "novenas",
    day: 3,
    intention: "To bring the Gospel to those who have not heard",
    text: `O missionary Saint Brendan, you carried the light of the Gospel to the farthest reaches of the known world. You evangelized Ireland, Scotland, Wales, and the islands of the Atlantic, founding monasteries and establishing communities of faith wherever you went. Your example inspires me to share the Good News with those around me — with my family, my neighbors, my coworkers, and even with strangers. Grant me the missionary zeal that burned in your heart, the willingness to go wherever God sends me, and the eloquence to proclaim His love effectively. Help me to see every encounter as an opportunity for evangelization, every conversation as a chance to speak of Christ. Remove from me the fear of rejection and the laziness that keeps me silent. O Saint Brendan, apostle of the Atlantic, obtain for me a burning desire to bring all souls to Christ.`,
  },
  {
    id: "sbr-np-4",
    novenaId: "novenas-saint-brendan",
    title: "Day 4 — Community: The Bond of Brotherhood",
    category: "novenas",
    day: 4,
    intention: "To build and cherish Christian community",
    text: `O communal Saint Brendan, you never journeyed alone. You gathered around you a band of faithful monks who shared your vision, your prayers, and your hardships. Together you sailed, together you prayed, together you endured. The monastery of Clonfert, which you founded, became a great center of learning and sanctity. Teach me the value of Christian community — the irreplaceable fellowship of believers who support, encourage, and strengthen one another on the way to heaven. Help me to be a faithful member of my parish, my family, and my community of faith. Grant me the grace to contribute my gifts for the building up of the Body of Christ, to bear the burdens of my brothers and sisters, and to rejoice in their successes as my own. O Saint Brendan, founder of holy communities, obtain for me a heart that loves the Church.`,
  },
  {
    id: "sbr-np-5",
    novenaId: "novenas-saint-brendan",
    title: "Day 5 — Trust: Sailing by Faith Alone",
    category: "novenas",
    day: 5,
    intention: "To increase trust in God's guiding hand",
    text: `O trusting Saint Brendan, you set sail across the Atlantic with no compass, no map, and no guarantee of safe return. Your only chart was faith; your only compass, the will of God. You trusted that the same God who created the seas would guide your little coracle safely through them. I pray today for an increase of trust in God's providential care. When I do not know the way, when the future is hidden in fog, when circumstances suggest that God has forgotten me, help me to trust as you trusted — blindly, completely, joyfully. Remind me that the One who holds the stars in their courses also holds my life in His hands. Nothing can happen to me outside of His will. O Saint Brendan, who sailed by faith alone, obtain for me an unshakeable trust in the guidance of Almighty God.`,
  },
  {
    id: "sbr-np-6",
    novenaId: "novenas-saint-brendan",
    title: "Day 6 — Discovery: Finding God's Wonders",
    category: "novenas",
    day: 6,
    intention: "To seek and discover the wonders of God",
    text: `O exploratory Saint Brendan, your voyages were marked by extraordinary encounters with the wonders of God's creation — floating islands of crystal, pillars of fire in the ocean, great fish that guided your boat, and at last the blessed land you sought. Your life reminds me that God has hidden treasures for those who seek Him with perseverance. I pray today for eyes of faith to see the wonders that surround me — the beauty of creation, the miracle of the Sacraments, the marvel of God's grace at work in ordinary life. Help me to approach each day with the spirit of a pilgrim and an explorer, searching for God's presence in every person, every event, every circumstance. May I never lose my sense of wonder before the mysteries of faith. O Saint Brendan, discoverer of divine wonders, obtain for me a spirit of holy curiosity.`,
  },
  {
    id: "sbr-np-7",
    novenaId: "novenas-saint-brendan",
    title: "Day 7 — Perseverance: Never Giving Up the Journey",
    category: "novenas",
    day: 7,
    intention: "To persevere in faith through every trial",
    text: `O persevering Saint Brendan, for seven years you sailed through unimaginable hardships — storms, hunger, thirst, fear, and uncertainty. Yet you never turned back, never abandoned your quest, never lost faith that God would bring you to your destination. Your perseverance is a rebuke to my own tendency to give up when the journey becomes difficult. I pray today for the grace of perseverance in all my spiritual endeavors. When prayer seems dry, when virtue seems impossible, when temptation seems overwhelming, when the spiritual life feels like a fruitless voyage across an endless sea, help me to press on. Grant me the determination to continue the journey of faith regardless of obstacles, trusting that God's promise is sure and His reward is certain. O Saint Brendan, apostle of perseverance, obtain for me the grace to finish the race and keep the faith.`,
  },
  {
    id: "sbr-np-8",
    novenaId: "novenas-saint-brendan",
    title: "Day 8 — Faith: The Substance of Things Hoped For",
    category: "novenas",
    day: 8,
    intention: "To grow in a living and active faith",
    text: `O faithful Saint Brendan, your entire enterprise was an act of faith — faith in the promises of God, faith in the reality of the heavenly homeland, faith that the visible world is not all there is. You sailed toward an island that human eyes had never seen because God had promised it existed. This is faith in its purest form. I pray today for such a faith — a faith that is not merely intellectual assent but a living trust that moves me to action. Help me to believe more deeply in the promises of Christ, in the reality of heaven, in the power of prayer, in the presence of God in the Eucharist. Strengthen my faith against the waves of doubt, the winds of secularism, and the storms of suffering. O Saint Brendan, hero of faith, obtain for me a faith that sails confidently toward the eternal shore.`,
  },
  {
    id: "sbr-np-9",
    novenaId: "novenas-saint-brendan",
    title: "Day 9 — Joy: The Delight of the Heavenly Homeland",
    category: "novenas",
    day: 9,
    intention: "To live in joyful hope of eternal life",
    text: `O joyful Saint Brendan, when at last you reached the Island of the Blessed, you found not merely a beautiful land but a foretaste of heaven itself — a place of perpetual peace, boundless joy, and the radiant presence of God. Your heart, which had longed for this destination through years of hardship, was finally satisfied. I pray today that the joy of heaven may fill my heart even now, while I am still on earth. Help me to live each day in the light of eternity, knowing that this world is but a passage and heaven is my true home. When trials come, remind me of the joy that awaits. When sorrows weigh upon me, lift my eyes to the blessed land where every tear will be wiped away. O Saint Brendan, who tasted the joy of heaven, obtain for me a heart that always rejoices in the hope of eternal glory.`,
  },

  // NOVENA TO SAINT KATERI TEKAKWITHA — Lily of the Mohawks
  // novenaId: "novenas-saint-kateri"

  {
    id: "skt-np-1",
    novenaId: "novenas-saint-kateri",
    title: "Day 1 — Conversion: Turning to Christ",
    category: "novenas",
    day: 1,
    intention: "To embrace a complete conversion of heart",
    text: `O pure Saint Kateri, Lily of the Mohawks, you who were born into paganism and orphaned by disease and war, yet chose to follow Jesus Christ with all your heart, intercede for me today. Your conversion was radical — you left behind the religion of your ancestors, the customs of your people, and the comforts of familiarity to embrace the faith of the missionaries who brought you the Gospel. Teach me the meaning of true conversion, which is not a single event but a lifelong turning of the heart toward Christ. Help me to leave behind whatever keeps me from following Jesus completely — my sins, my attachments, my fears, my pride. Grant me the courage to begin anew each day, to repent of my failures, and to walk the narrow path that leads to eternal life. O Saint Kateri, converted soul and devoted disciple, obtain for me the grace of a complete and lasting conversion.`,
  },
  {
    id: "skt-np-2",
    novenaId: "novenas-saint-kateri",
    title: "Day 2 — Purity: The White Lily of Christ",
    category: "novenas",
    day: 2,
    intention: "To cultivate purity of heart and body",
    text: `O pure Saint Kateri, whose name means "she who bumps into things" in the Mohawk language, yet whose soul was the most beautiful in its innocence, you maintained your purity in a world that knew nothing of Christian chastity. Despite the loss of your parents, the ravages of smallpox that scarred your face, and the pressures of your tribe, you preserved your virginity for Christ and your innocence before God. I pray today for the virtue of purity in a world saturated with impurity. Protect my mind from lewd images, my heart from disordered desires, my body from sexual sin. Help me to see every person as a temple of the Holy Spirit, to honor the dignity of every human body, and to live as a child of God in thought, word, and deed. O Saint Kateri, lily of purity, obtain for me a clean heart and a steadfast spirit.`,
  },
  {
    id: "skt-np-3",
    novenaId: "novenas-saint-kateri",
    title: "Day 3 — Suffering: Offering Pain to God",
    category: "novenas",
    day: 3,
    intention: "To unite my sufferings with those of Christ",
    text: `O suffering Saint Kateri, you endured the loss of your parents at the age of four, the disfigurement of smallpox, the persecution of your people for your Christian faith, and an early death at just twenty-four years of age. Yet you never complained, never cursed God, never lost your trust in divine providence. Instead, you offered every suffering to God as a sacrifice of love. I bring before you today my own sufferings — physical pains, emotional wounds, spiritual struggles, and the daily crosses that I bear. Help me to see in them not merely burdens to be endured but opportunities to unite my heart with the Sacred Heart of Jesus on the cross. Teach me to offer my pain for the conversion of sinners, the relief of the holy souls in purgatory, and the needs of the Church. O Saint Kateri, who offered your sufferings with love, obtain for me the grace to unite my crosses to Christ's.`,
  },
  {
    id: "skt-np-4",
    novenaId: "novenas-saint-kateri",
    title: "Day 4 — Nature: Honoring God's Creation",
    category: "novenas",
    day: 4,
    intention: "To reverence the natural world as God's handiwork",
    text: `O Saint Kateri, daughter of the forest, you who grew up among the rivers, mountains, and woodlands of what is now New York State, you understood the beauty and goodness of God's creation. As a Mohawk, you were deeply connected to the land, the animals, and the seasons. Your faith did not destroy this connection but deepened it, for you recognized in everyCreated thing the loving hand of the Creator. I pray today for a deeper appreciation of the natural world that God has entrusted to our care. Help me to see His majesty in the mountains, His power in the oceans, His tenderness in the flowers, and His wisdom in the stars. Grant me the responsibility to protect and preserve the environment, not as owners but as stewards of God's good gifts. O Saint Kateri, lover of creation, obtain for me a heart that honors God in all His works.`,
  },
  {
    id: "skt-np-5",
    novenaId: "novenas-saint-kateri",
    title: "Day 5 — Prayer: Conversing with God",
    category: "novenas",
    day: 5,
    intention: "To deepen my life of prayer",
    text: `O prayerful Saint Kateri, you spent hours in communion with God, lifting your heart to Him in the forests and fields of your homeland. You prayed with the rosary that the Jesuit missionaries had taught you, you prayed in the silence of your heart, you prayed with your whole being — mind, body, and spirit. Prayer was not an obligation for you but the very air you breathed. I pray today for a richer and more constant life of prayer. Help me to speak to God as a friend speaks to a friend, to listen for His voice in the depths of my soul, to pray not only with words but with the desires of my heart. Teach me to pray in all circumstances — in joy and in sorrow, in work and in rest, in the morning and in the evening. O Saint Kateri, woman of unceasing prayer, obtain for me the grace to pray without ceasing.`,
  },
  {
    id: "skt-np-6",
    novenaId: "novenas-saint-kateri",
    title: "Day 6 — Charity: Love in Action",
    category: "novenas",
    day: 6,
    intention: "To practice concrete acts of love and mercy",
    text: `O charitable Saint Kateri, you who showed kindness to every creature — to the sick, the elderly, the children, and even to the animals of the forest — teach me to love as Christ loved. Despite your own suffering and poverty, you were always ready to share what you had, to comfort those who mourned, to visit those who were ill. Your charity was not theoretical but practical, not distant but personal. I pray today for the grace to put love into action. Help me to see Christ in the faces of the poor, the hungry, the lonely, and the marginalized. Give me the courage to serve others without counting the cost, to give generously of my time, talent, and treasure. May my charity be a reflection of the love of God, poured out upon me through the Sacred Heart of Jesus. O Saint Kateri, apostle of charity, obtain for me a heart that loves without limit.`,
  },
  {
    id: "skt-np-7",
    novenaId: "novenas-saint-kateri",
    title: "Day 7 — Youth: A Model for Young Catholics",
    category: "novenas",
    day: 7,
    intention: "To inspire young people to follow Christ",
    text: `O young Saint Kateri, you who embraced the faith as a teenager and gave your life to Christ in the bloom of youth, you are a powerful model for the young people of today. In an age when many young Catholics leave the Church, when peer pressure and secular culture pull youth away from the faith, your example shines like a beacon. You chose Christ over comfort, holiness over popularity, heaven over earth. I pray today for all young people, that they may find in your story the courage to live their faith boldly. Help parents and educators to form young hearts in the ways of holiness. Protect the youth of the Church from the snares of the evil one, from the lies of a culture that denies the transcendent. Grant them the grace to say, as you did, "I am a Christian, and I will live as a Christian." O Saint Kateri, patroness of young people, intercede for the youth of the world.`,
  },
  {
    id: "skt-np-8",
    novenaId: "novenas-saint-kateri",
    title: "Day 8 — Courage: Standing Firm in the Faith",
    category: "novenas",
    day: 8,
    intention: "To have courage in the face of opposition",
    text: `O courageous Saint Kateri, when you converted to Christianity, you faced the fury of your own tribe. Your uncle and chief tried to force you to abandon your faith. The medicine men sought to frighten you with threats and sorcery. Yet you stood firm, answering only with the words, "I love Jesus Christ." This courage was not born of stubbornness but of a faith so deep that no persecution could shake it. I pray today for the courage to stand firm in my faith when it costs me something — when I am mocked for my beliefs, when I am pressured to compromise my values, when standing with Christ means standing alone. Help me to remember that He who died for me will never abandon me, and that the martyrs who went before me are praying for me. O Saint Kateri, courageous witness, obtain for me the fortitude to be faithful to Christ at all times.`,
  },
  {
    id: "skt-np-9",
    novenaId: "novenas-saint-kateri",
    title: "Day 9 — Heaven: The Eternal Reward",
    category: "novenas",
    day: 9,
    intention: "To live in hope of heaven",
    text: `O heavenly Saint Kateri, your last words on earth were the sweetest testimony of faith: "I love Jesus Christ. I love Him because I have seen Him, loved Him, desired Him, and served Him. I want to go to heaven." And so you did, departing this life at the age of twenty-four and entering into the eternal joy of God's presence. You who had suffered so much on earth found in heaven the perfect happiness that had eluded you in this world. I pray today for the grace to live with heaven always before my eyes, to make every decision in light of eternity, to store up treasures where moth and rust cannot destroy. When I am tempted to set my heart on earthly things, remind me of the infinitely greater glory that awaits the faithful. O Saint Kateri, lily of heaven, obtain for me the grace to live and die in such a way that I may one day join you in the eternal paradise of God.`,
  },

  // NOVENA TO SAINT OSCAR ROMERO — Martyr for Justice
  // novenaId: "novenas-saint-oscar-romero"

  {
    id: "sor-np-1",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 1 — Justice: The Rights of the Poor",
    category: "novenas",
    day: 1,
    intention: "To defend the dignity and rights of the poor",
    text: `O holy Oscar Romero, Archbishop and Martyr, you who gave your life defending the poor and oppressed of El Salvador, intercede for me today. You who once were a quiet, academic bishop were transformed by the Holy Spirit into the voice of the voiceless, the champion of the defenseless, the shepherd who stood between the wolves and the sheep. Teach me that justice is not optional for Christians but a fundamental requirement of the Gospel. Help me to open my eyes to the suffering of the poor, the exploitation of the workers, the cries of the widows and orphans. Give me the courage to speak out against injustice even when it is dangerous to do so. O Saint Oscar Romero, martyr for justice, obtain for me a heart that burns with the same passion for righteousness that inflamed your sacred heart.`,
  },
  {
    id: "sor-np-2",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 2 — Courage: Speaking Truth to Power",
    category: "novenas",
    day: 2,
    intention: "To speak the truth boldly regardless of consequences",
    text: `O courageous Saint Oscar Romero, you stood before the military dictators, the death squads, and the powerful elite of El Salvador and proclaimed: "In the name of God, and in the name of this suffering people, I ask you, I beg you, I order you — stop the repression!" You knew that these words would cost you your life, and you spoke them anyway, because the truth of the Gospel demanded it. Grant me the courage to speak truth to power in my own life — to tell the truth when lies would be easier, to defend the innocent when silence would be safer, to stand for what is right when the majority chooses what is convenient. Help me to remember that perfect love casts out fear, and that the truth will set us free. O Saint Oscar Romero, fearless witness to truth, obtain for me the courage to proclaim the Gospel without compromise.`,
  },
  {
    id: "sor-np-3",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 3 — Solidarity: Standing with the Suffering",
    category: "novenas",
    day: 3,
    intention: "To stand in solidarity with those who suffer",
    text: `O compassionate Saint Romero, you chose to live among the poor, to eat their food, to walk their streets, to feel their pain. When Jesuit priests, catechists, and lay leaders were murdered for their faith, you did not flee but remained with your flock, sharing their danger, weeping their tears, carrying their cross. You understood that a shepherd who does not share the fate of his sheep is no shepherd at all. I pray today for the grace of solidarity — the willingness to stand with those who suffer, to share their burdens, to enter into their pain. Help me not to look away from suffering but to draw near. Grant me the compassion to feel the wounds of Christ in the bodies of His poor. O Saint Oscar Romero, shepherd of the suffering, obtain for me a heart that is inseparable from the hearts of the afflicted.`,
  },
  {
    id: "sor-np-4",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 4 — Truth: Proclaiming the Word of God",
    category: "novenas",
    day: 4,
    intention: "To faithfully proclaim the fullness of Catholic truth",
    text: `O truthful Saint Oscar Romero, you used your radio broadcasts, your homilies, and your pastoral letters to proclaim the Word of God with clarity and power. In a time when the truth was being suppressed by both government and military, you became a beacon of light, teaching the faithful the social doctrine of the Church and the liberating message of the Gospel. I pray today for the grace to love and proclaim the fullness of Catholic truth — not watered down to suit the culture, not distorted to serve political agendas, but in its entirety and with all its demands. Help me to study Sacred Scripture, to know the teachings of the Church, and to share what I know with others. May I never be ashamed of the Gospel, for it is the power of God for salvation. O Saint Oscar Romero, herald of truth, obtain for me a love for the Word of God that burns within me like a fire.`,
  },
  {
    id: "sor-np-5",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 5 — Martyrdom: Laying Down One's Life",
    category: "novenas",
    day: 5,
    intention: "To be willing to suffer for the faith",
    text: `O glorious martyr Saint Oscar Romero, on March 24, 1980, while celebrating the Holy Mass in the Chapel of the Divine Providence Hospital, an assassin's bullet struck you down at the altar, and you offered your life as a sacrifice alongside the Eucharistic victim. Your martyrdom was the culmination of a life increasingly conformed to the Passion of Christ. You had received death threats, you had seen your friends murdered, you had been vilified by the powerful — yet you continued to celebrate Mass, to preach the Gospel, and to serve the poor. I pray today for the grace of martyrdom — not necessarily the shedding of my blood, but the daily dying to self that is the essence of Christian discipleship. Help me to take up my cross each day and follow Christ, to die to my ego, my will, my comfort, so that I may live for Him alone. O Saint Oscar Romero, holy martyr, obtain for me the grace to die to self and live for Christ.`,
  },
  {
    id: "sor-np-6",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 6 — Pastoral Love: The Good Shepherd's Heart",
    category: "novenas",
    day: 6,
    intention: "To shepherd others with Christ's love",
    text: `O pastoral Saint Romero, you grew into your role as Archbishop by allowing the Holy Spirit to transform your heart. Initially cautious and diplomatic, you became the bold and loving shepherd your people needed. You visited the sick, comforted the bereaved, baptized the children, and confirmed the faithful — all while under the shadow of death. Your pastoral love was inseparable from your prophetic witness. I pray today for all pastors of the Church — bishops, priests, deacons, and lay ministers. Grant them the pastoral heart of Christ, the courage of Saint Romero, and the wisdom to lead souls to heaven. Help me also to exercise a form of pastoral care in my own sphere of influence, to tend the spiritual needs of those entrusted to my care. O Saint Oscar Romero, model of pastoral love, obtain for all shepherds the heart of the Good Shepherd.`,
  },
  {
    id: "sor-np-7",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 7 — Peace: The Fruit of Justice",
    category: "novenas",
    day: 7,
    intention: "To work for true and lasting peace",
    text: `O peace-loving Saint Romero, you knew that true peace is not the mere absence of conflict but the presence of justice, love, and reconciliation. You prayed for peace in El Salvador, but you understood that peace without justice is merely oppression. You worked for reconciliation, but you knew that reconciliation without truth is mere sentimentality. I pray today for peace in our world — in the homes torn by domestic violence, in the streets plagued by crime, in the nations divided by ideology. Help me to be an instrument of peace in my own community, beginning with the peace of Christ in my own heart. Grant me the courage to work for the conditions that make peace possible: justice, truth, mercy, and love. O Saint Oscar Romero, apostle of peace, obtain for me the grace to be a peacemaker according to the heart of Christ.`,
  },
  {
    id: "sor-np-8",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 8 — Hope: Trusting in God's Plan",
    category: "novenas",
    day: 8,
    intention: "To maintain hope in the darkest times",
    text: `O hopeful Saint Romero, even as the darkness of violence and death closed in around you, you never lost hope in the triumph of God. You knew that the same God who raised Jesus from the dead would raise up His people from the ashes of persecution. Your hope was not naive optimism but a deep trust in the providence of the Almighty. I pray today for the virtue of hope in my own life. When I am tempted to despair, when the news is filled with violence and hatred, when my own spiritual life seems barren and God seems distant, help me to cling to the hope that does not disappoint. Remember me before the Lord, and remind me that "God will not allow us to be tempted beyond our strength" and that "all things work together for good for those who love God." O Saint Oscar Romero, beacon of hope, obtain for me an unshakeable confidence in God's victory.`,
  },
  {
    id: "sor-np-9",
    novenaId: "novenas-saint-oscar-romero",
    title: "Day 9 — Legacy: The Fruit of Faithful Witness",
    category: "novenas",
    day: 9,
    intention: "To leave a legacy of faith for future generations",
    text: `O legacy-rich Saint Oscar Romero, your death on the altar did not end your mission but fulfilled it. The people of El Salvador and of the entire world have been inspired by your example for decades. The Church has recognized your holiness by canonizing you as a saint, and your words continue to echo across the centuries: "If they kill me, I shall arise in the Salvadoran people." I pray today that my own life may bear fruit that lasts for eternity. Help me to live in such a way that my faith, my charity, and my witness will inspire those who come after me. Grant me the grace to plant seeds of holiness in the hearts of others, seeds that will bloom long after I am gone. May my legacy be not worldly success but faithful discipleship, not fame but holiness, not power but service. O Saint Oscar Romero, whose legacy endures forever, obtain for me the grace to build a life that glorifies God and benefits His Church.`,
  },

  // NOVENA TO ALL HOLY MARTYRS OF AFRICA
  // novenaId: "novenas-all-saints-africa"

  {
    id: "sma-np-1",
    novenaId: "novenas-all-saints-africa",
    title: "Day 1 — Remembrance: Honoring the Blood of the Martyrs",
    category: "novenas",
    day: 1,
    intention: "To remember and honor the African martyrs",
    text: `O all holy Martyrs of Africa, whose names are known to God even when they are forgotten by the world, I remember you today with reverence and gratitude. From the sands of ancient North Africa, where Saints Perpetua, Felicity, Cyprian, and Augustine gave their witness, to the modern era, when millions of African Christians have suffered and died for Christ, the blood of the martyrs has been the seed of the Church on this great continent. I pray today that the Church may never forget your sacrifice. Help me to learn your stories, to honor your memory, and to draw inspiration from your courage. May your suffering not be in vain but continue to bear fruit in the conversion of souls and the strengthening of the faith throughout Africa and the world. O holy Martyrs of Africa, whose witness adorns the crown of the Church, intercede for us before the throne of God.`,
  },
  {
    id: "sma-np-2",
    novenaId: "novenas-all-saints-africa",
    title: "Day 2 — Faith: Unshakable Belief in Christ",
    category: "novenas",
    day: 2,
    intention: "To grow in a faith that endures all trials",
    text: `O steadfast African Martyrs, you who professed your faith in Christ Jesus before Roman proconsuls, tribal kings, and modern persecutors, your faith was tested in the most extreme circumstances and found unbreakable. In the arenas of Carthage, in the prisons of Numidia, in the villages of modern Uganda, Sudan, and Nigeria, you confessed Christ with your dying breath. Your faith was not theoretical but deeply personal — you knew the One in whom you believed, and you were convinced that He was able to guard what you had entrusted to Him. I pray today for a faith like yours, a faith that is more precious to me than life itself. Help me to trust in Christ through every trial, to cling to Him when the world presses me to let go. O holy Martyrs of Africa, obtain for me a faith that cannot be shaken by any storm.`,
  },
  {
    id: "sma-np-3",
    novenaId: "novenas-all-saints-africa",
    title: "Day 3 — Courage: Fearless Before the Executioner",
    category: "novenas",
    day: 3,
    intention: "To have holy courage in the face of danger",
    text: `O fearless Martyrs of Africa, you who faced swords, flames, clubs, machetes, and bullets without flinching, your courage was not the recklessness of the fool but the holy boldness of those who know that death has lost its sting. You who were torn apart by wild beasts in the amphitheater, you who were crucified on the roads of Numidia, you who were massacred in the villages of the twentieth century — you showed the world that the Spirit of God transforms ordinary people into heroes of supernatural valor. I pray today for such courage in my own life. When I am tempted to compromise my faith out of fear of ridicule, rejection, or persecution, strengthen me by the memory of your witness. Help me to remember that the one who endures to the end will be saved. O courageous Martyrs of Africa, obtain for me a spirit of holy boldness.`,
  },
  {
    id: "sma-np-4",
    novenaId: "novenas-all-saints-africa",
    title: "Day 4 — Forgiveness: Loving the Persecutors",
    category: "novenas",
    day: 4,
    intention: "To forgive those who harm me",
    text: `O forgiving Martyrs of Africa, you who prayed for your executioners as you lay dying, who forgave the hands that struck you down, who loved your persecutors even as they shed your blood — your example of forgiveness is the highest manifestation of Christian charity. You followed the words of Christ on the cross: "Father, forgive them, for they know not what they do." In a continent often torn by tribal violence, ethnic hatred, and religious extremism, your forgiveness shines as a light of reconciliation. I pray today for the grace to forgive as you forgave. Help me to release every grudge, every bitterness, every desire for revenge that lurks in my heart. Grant me the supernatural strength to pray for those who hurt me, to love those who hate me, to bless those who curse me. O holy Martyrs of Africa, who forgave your murderers, obtain for me a heart of boundless mercy.`,
  },
  {
    id: "sma-np-5",
    novenaId: "novenas-all-saints-africa",
    title: "Day 5 — Unity: One in Christ Across Every Division",
    category: "novenas",
    day: 5,
    intention: "To work for unity among all African Christians",
    text: `O unified Martyrs of Africa, you who came from many tribes, languages, and nations yet were made one in the blood of Christ, you embody the prayer of Jesus that all His followers "may be one." Whether from the Berber tribes of ancient North Africa, the Bantu peoples of the south, or the diverse communities of the continent today, you were united in faith, hope, and love. I pray today for the unity of Christians in Africa and throughout the world. Heal the divisions that weaken the witness of the Church. Break down the walls of tribalism, nationalism, racism, and sectarianism that prevent the full communion of believers. Help me to see in every Christian — regardless of race, nationality, or denomination — a brother or sister in Christ. O holy Martyrs of Africa, who transcended every division in Christ, obtain for me a heart that seeks unity above all else.`,
  },
  {
    id: "sma-np-6",
    novenaId: "novenas-all-saints-africa",
    title: "Day 6 — Persecution: The Cost of Discipleship",
    category: "novenas",
    day: 6,
    intention: "To accept suffering as the price of following Christ",
    text: `O persecuted Martyrs of Africa, you who paid the ultimate price for following Christ, you understood that persecution is not an anomaly of the Christian life but its normal expectation. Our Lord Himself warned us: "If the world hates you, know that it has hated me before it hated you." You who have suffered under Roman emperors, Islamic conquerors, communist dictators, and religious extremists bear witness to the eternal truth that the Church is born from the blood of the Lamb. I pray today for all Christians who are persecuted around the world, especially in Africa where the Church continues to suffer. Help me to count my own sufferings as small compared to yours, and to unite them with yours for the glory of God. Grant me the grace to accept persecution as a privilege, not a punishment. O holy Martyrs of Africa, who suffered for Christ, obtain for me the grace to embrace the cross.`,
  },
  {
    id: "sma-np-7",
    novenaId: "novenas-all-saints-africa",
    title: "Day 7 — Hope: The Promise of Resurrection",
    category: "novenas",
    day: 7,
    intention: "To maintain hope in the promise of eternal life",
    text: `O hopeful Martyrs of Africa, you who endured the most extreme suffering because you believed in the resurrection of the body and life everlasting, your hope was vindicated when you passed from the agony of martyrdom to the glory of heaven. You who were tortured on earth now rejoice in the presence of God. You who were killed by the sword now wield the palm branch of victory. I pray today that your hope may become my hope. When I am discouraged by the trials of life, when suffering seems pointless, when death seems like the final word, remind me that it is not — that Christ has conquered death, and that those who die in Him will live with Him forever. Help me to set my mind on things above, where Christ is seated at the right hand of God. O holy Martyrs of Africa, who hope in the resurrection, obtain for me a hope that is steadfast and sure.`,
  },
  {
    id: "sma-np-8",
    novenaId: "novenas-all-saints-africa",
    title: "Day 8 — Intercession: Praying for the Church in Africa",
    category: "novenas",
    day: 8,
    intention: "To entrust the African Church to the martyrs' intercession",
    text: `O intercessory Martyrs of Africa, you who stand before the throne of God in the white robes of those who have washed their garments in the blood of the Lamb, I ask you to intercede for the Church in Africa today. The continent that produced you continues to be a land of both tremendous faith and tremendous trial. Christians are still being persecuted, churches are still being burned, faithful are still being killed for their belief in Christ. I pray that your intercession may bring protection, strength, and perseverance to the Church in Africa. May the faith continue to grow despite all opposition. May new martyrs be raised up if God wills, but may the era of peace also come. I also ask you to intercede for me personally, for my intentions, and for my family. O holy Martyrs of Africa, powerful intercessors, present my petitions before the King of Martyrs.`,
  },
  {
    id: "sma-np-9",
    novenaId: "novenas-all-saints-africa",
    title: "Day 9 — Victory: The Triumph of Christ and His Church",
    category: "novenas",
    day: 9,
    intention: "To proclaim the victory of Christ over sin and death",
    text: `O victorious Martyrs of Africa, you who have already won the crown of glory, I celebrate today the triumph that is yours and that awaits all who persevere in faith. The victory of Christ on the cross is the victory that you share, the victory over sin, over death, over the powers of darkness. Despite centuries of persecution, the Church in Africa is not destroyed but flourishes — this is the work of God, who uses the blood of martyrs to water the vineyard of His Church. I pray today with the confidence of those who know the ending of the story — Christ has won, Christ is victorious, Christ will come again. Help me to live each day in the light of this victory, to face every challenge with the assurance that God is in control, to proclaim with joy that the Lord is risen and His victory is complete. O holy Martyrs of Africa, triumphant in glory, obtain for me the grace to live and die in the victory of Christ.`,
  },

  // NOVENA TO JESUS OF NAZARETH
  // novenaId: "novenas-jesus-nazareth"

  {
    id: "sjn-np-1",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 1 — Childhood: The Incarnation of God",
    category: "novenas",
    day: 1,
    intention: "To contemplate the mystery of God becoming man",
    text: `O Jesus of Nazareth, Eternal Word of the Father, who for our sake became a little child in the womb of the Blessed Virgin Mary, I adore and worship You today in the mystery of Your infancy. You who are God from all eternity, who created the heavens and the earth, who sustains all things by the word of Your power — You became small, helpless, and dependent upon a human mother. This is the scandal of the Incarnation, the mystery that扑使 the angels to wonder and the saints to adore. I pray today for the grace to contemplate this mystery with awe and reverence. Help me to understand that in becoming human, You did not cease to be God, but united Your divine nature to our humanity forever. May I never take for granted the astonishing reality that God became man so that man might become like God. O Jesus of Nazareth, Word made flesh, I worship You in Your holy childhood.`,
  },
  {
    id: "sjn-np-2",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 2 — Hidden Life: Holiness in Obscurity",
    category: "novenas",
    day: 2,
    intention: "To find God in the ordinary moments of life",
    text: `O Jesus of Nazareth, for nearly thirty years You lived in obscurity in the small town of Nazareth, working as a carpenter, obeying Mary and Joseph, living a life of perfect humility and hiddenness. In a world that worships fame, success, and public recognition, Your hidden life teaches me that holiness does not require greatness in the eyes of the world. I pray today for the grace to find God in the ordinary moments of my life — in my daily work, in my family responsibilities, in the mundane tasks that fill my hours. Help me to understand that every moment lived in the presence of God is sacred, that every act of love offered to Him is precious, that the path to heaven is paved not with extraordinary deeds but with faithful performance of my daily duties. O Jesus of Nazareth, model of the hidden life, sanctify my ordinary days.`,
  },
  {
    id: "sjn-np-3",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 3 — Baptism: The Beginning of Public Ministry",
    category: "novenas",
    day: 3,
    intention: "To renew my baptismal promises with fervor",
    text: `O Jesus of Nazareth, when You presented Yourself for baptism in the Jordan River, the heavens were opened, the Holy Spirit descended upon You like a dove, and the voice of the Father proclaimed: "This is my beloved Son, in whom I am well pleased." Your baptism marked the beginning of Your public ministry and revealed Your identity as the Son of God. I pray today for a renewal of my own baptismal promises. I renounce Satan and all his works and all his empty promises. I believe in God the Father Almighty, Creator of heaven and earth, and in Jesus Christ, His only Son, our Lord. Help me to live in a way that is worthy of my baptism, to put on the new self that was created in holiness and truth. O Jesus of Nazareth, baptized in the Jordan, renew in me the grace of my baptism.`,
  },
  {
    id: "sjn-np-4",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 4 — Temptation: Victory Over the Evil One",
    category: "novenas",
    day: 4,
    intention: "To resist temptation with the armor of God",
    text: `O Jesus of Nazareth, after Your baptism, the Holy Spirit led You into the desert to be tempted by the devil for forty days. You fasted, You prayed, and You endured three direct temptations — and You conquered each one by the power of God's Word and the strength of Your divine-human will. Your victory over temptation is my hope, for it shows that grace can overcome any assault of the evil one. I pray today for the strength to resist the temptations that beset me — the temptation to pride, to lust, to greed, to despair. Help me to use the weapons that You have given me: prayer, fasting, the Word of God, and the Sacraments. When the devil whispers his lies, help me to answer as You did: "Man shall not live by bread alone, but by every word that comes from the mouth of God." O Jesus of Nazareth, conqueror of Satan, grant me victory over every temptation.`,
  },
  {
    id: "sjn-np-5",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 5 — Ministry: The compassionate Teacher",
    category: "novenas",
    day: 5,
    intention: "To follow Christ in serving others",
    text: `O Jesus of Nazareth, when You began Your public ministry, You traveled throughout Galilee and Judea teaching in the synagogues, healing the sick, casting out demons, and proclaiming the Kingdom of God. You were moved with compassion for the crowds who were "like sheep without a shepherd." Your ministry was one of total self-giving, of tireless service, of boundless love for every soul. I pray today for the grace to follow Your example in serving others. Help me to see the needs of those around me, to respond with compassion rather than indifference, to give of myself without counting the cost. Grant me the energy to do God's work, the wisdom to know what is most needed, and the humility to serve even when no one notices. O Jesus of Nazareth, servant of all, teach me to serve as You served.`,
  },
  {
    id: "sjn-np-6",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 6 — Teaching: The Words of Eternal Life",
    category: "novenas",
    day: 6,
    intention: "To listen to and live by the teachings of Christ",
    text: `O Jesus of Nazareth, divine Teacher, Your words are "spirit and life" (John 6:63). You spoke as no one ever spoke before — with authority, with wisdom, with tenderness, with power. The Beatitudes, the Parables, the discourses of the Last Supper — all of these are treasures of infinite value, the words of the Creator to His creatures. I pray today for the grace to listen to Your teaching with an open heart, to understand it with a docile mind, and to live it with a willing spirit. Help me to study Your words in Sacred Scripture, to contemplate them in prayer, and to practice them in daily life. When Your teachings challenge my comfortable assumptions, give me the humility to accept them. When the world mocks the Gospel, give me the courage to proclaim it. O Jesus of Nazareth, Wisdom of God, speak Your words to my heart and give me the grace to obey.`,
  },
  {
    id: "sjn-np-7",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 7 — Miracles: Signs of Divine Power",
    category: "novenas",
    day: 7,
    intention: "To believe in Christ's power over all creation",
    text: `O Jesus of Nazareth, You confirmed Your divine mission with signs and wonders that manifested the power of God. You turned water into wine, fed five thousand with five loaves, walked upon the sea, calmed the storm, healed the blind, cured the lepers, and raised the dead. These miracles were not mere spectacles but signs of the Kingdom of God, revealing that in You the power of God is present to heal, restore, and save. I pray today for an increase of faith in Your divine power. Help me to believe that the same Jesus who performed these miracles is present and active in my life today. Nothing is impossible for You — no sin is too great to be forgiven, no suffering is too deep to be redeemed, no situation is too hopeless to be transformed. O Jesus of Nazareth, worker of miracles, increase my faith in Your omnipotent love.`,
  },
  {
    id: "sjn-np-8",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 8 — Passion: The Sacrifice of the Cross",
    category: "novenas",
    day: 8,
    intention: "To unite my sufferings with the Passion of Christ",
    text: `O Jesus of Nazareth, Man of Sorrows, You who were despised and rejected, acquainted with grief, bruised for our iniquities, chastised for our peace — I contemplate today the agony of Your Passion. From the Garden of Gethsemane, where You sweated blood, to the house of Caiaphas, where You were mocked and blindfolded, to the praetorium, where You were scourged and crowned with thorns, to the Via Dolorosa, where You carried the cross, to Calvary, where You were nailed to the wood and lifted up between heaven and earth — You endured it all for love of me. I pray today that Your Passion may not be wasted in my life. Help me to unite my sufferings with Yours, to offer my crosses as You offered Yours, to bear my pain with the same love that sustained You. O Jesus of Nazareth, crucified Savior, I embrace Your cross and offer mine with You.`,
  },
  {
    id: "sjn-np-9",
    novenaId: "novenas-jesus-nazareth",
    title: "Day 9 — Resurrection: The Dawn of New Life",
    category: "novenas",
    day: 9,
    intention: "To rejoice in the triumph of Christ over death",
    text: `O Jesus of Nazareth, risen from the dead, You who conquered sin and death by the power of Your resurrection, I rejoice in You today! The tomb is empty, the stone has been rolled away, the angels proclaim that He is not here — He is risen! The resurrection is the foundation of our faith, the guarantee of our own resurrection, the triumph of light over darkness, life over death, hope over despair. I pray today that the power of Your resurrection may transform my life. Help me to live as a child of the resurrection, to rise from the death of sin to the life of grace, to leave behind the tomb of my old self and walk in the newness of life. When I am buried under the weight of sorrow, failure, or fear, raise me up by Your almighty power. O Jesus of Nazareth, risen Lord, You are the resurrection and the life, and whoever believes in You will never die.`,
  },

  // NOVENA FOR THE SACRAMENT OF RECONCILIATION
  // novenaId: "novenas-sacrament-reconciliation"

  {
    id: "src-np-1",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 1 — Contrition: The Sorrow of a Wounded Heart",
    category: "novenas",
    day: 1,
    intention: "To cultivate true contrition for my sins",
    text: `O merciful Lord Jesus Christ, You who instituted the Sacrament of Reconciliation and entrusted to Your Apostles the power to forgive sins, I come before You today with a heart that desires true contrition. I am sorry for my sins not merely because of the punishment I deserve but because they have offended You, my loving God, who is infinitely good and deserving of all my love. Grant me the grace of perfect contrition — a sorrow born not of fear but of love, a sorrow that springs from having wounded the Sacred Heart that loves me beyond measure. Help me to examine my conscience honestly, to recognize the gravity of my offenses, and to detest them with all the power of my soul. O Jesus, good Shepherd, grant me a heart that weeps for sin and longs for the healing of reconciliation.`,
  },
  {
    id: "src-np-2",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 2 — Confession: Bringing Sin into the Light",
    category: "novenas",
    day: 2,
    intention: "To approach the confessional with humility",
    text: `O gentle Jesus, You who said "Confess your sins to one another" (James 5:16) and who breathed on the Apostles saying "Whose sins you forgive are forgiven them" (John 20:23), I praise You for the gift of the Sacrament of Confession. I confess that I often resist going to confession, that pride holds me back, that fear of exposure keeps my sins hidden in darkness. Yet You have commanded us to bring our sins into the light of Your mercy, to name them before a priest who acts in Your person. Grant me the humility to confess my sins honestly and completely, holding nothing back. Help me to understand that the confessional is not a place of judgment but a place of healing, not a courtroom but a hospital for souls. O Jesus, physician of souls, give me the courage to bring my wounds to You in the Sacrament of Reconciliation.`,
  },
  {
    id: "src-np-3",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 3 — Absolution: The Words of Divine Mercy",
    category: "novenas",
    day: 3,
    intention: "To receive absolution with grateful faith",
    text: `O compassionate Jesus, the words of absolution spoken by the priest — "I absolve you from your sins in the name of the Father, and of the Son, and of the Holy Spirit" — are the most healing words in the world. Through these words, You Yourself speak to the soul, You Yourself lift the burden of guilt, You Yourself restore the state of grace. I praise You for the power You have given to Your Church to forgive sins. Help me to receive absolution with living faith, to believe that in that moment my sins are truly forgiven, that my soul is truly cleansed, that I am truly restored to the friendship of God. May I never take this miracle of mercy for granted but approach the Sacrament with reverence and gratitude. O Jesus, fountain of mercy, I thank You for the gift of absolution.`,
  },
  {
    id: "src-np-4",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 4 — Penance: Making Amends for Sin",
    category: "novenas",
    day: 4,
    intention: "To fulfill my penance with love and sincerity",
    text: `O just and merciful Lord, after absolution You do not leave me as I was but give me the grace to make amends through the penance imposed in confession. Penance is not punishment but medicine — a means of repairing the damage that sin has caused, of strengthening the will against future temptation, of demonstrating the sincerity of my conversion. I pray today for the grace to fulfill my penance with love, not reluctantly or carelessly but as a genuine act of reparation. Help me to understand that every prayer I offer, every almsgiving I perform, every sacrifice I make as penance is a participation in the healing work of Christ. May my penance bear abundant fruit in the transformation of my life. O Jesus, repairer of souls, help me to make worthy amends for my sins through sincere penance.`,
  },
  {
    id: "src-np-5",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 5 — Frequency: The Habit of Grace",
    category: "novenas",
    day: 5,
    intention: "To make regular confession a part of my spiritual life",
    text: `O gracious Lord, the saints have recommended frequent confession not because we sin greatly each week but because frequent encounter with Your mercy strengthens us in holiness. Regular confession is like regular exercise for the soul — it keeps the spiritual muscles strong, it maintains the habits of self-examination and humility, it provides ongoing healing for the wounds of daily sin. I pray today for the grace to make confession a regular part of my spiritual life. Help me to go to confession monthly or even more frequently, not out of obligation but out of love for Your mercy. Remove from me the excuses that keep me away from this life-giving Sacrament. Grant me the discipline to examine my conscience regularly and the courage to seek forgiveness promptly. O Jesus, source of all grace, make me a frequent and faithful penitent.`,
  },
  {
    id: "src-np-6",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 6 — Examination of Conscience: Honest Self-Reflection",
    category: "novenas",
    day: 6,
    intention: "To examine my conscience with thoroughness and honesty",
    text: `O enlightening Holy Spirit, who guides the soul into all truth, I pray today for the grace of a thorough and honest examination of conscience. Too often I rush through this examination, glossing over my sins, minimizing my faults, comparing myself favorably with others. But You, O Lord, see my soul as it truly is — and You invite me to see it also with the light of faith. Help me to examine my life against the standard of the Ten Commandments, the Beatitudes, the teachings of Christ, and the duties of my state of life. Give me the honesty to admit what I have done and what I have failed to do, the humility to acknowledge my weakness, and the determination to improve. O Jesus, mirror of the soul, help me to see myself as You see me and to seek the healing of Your mercy.`,
  },
  {
    id: "src-np-7",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 7 — God's Mercy: An Ocean Without Shore",
    category: "novenas",
    day: 7,
    intention: "To trust in the boundless mercy of God",
    text: `O infinitely merciful Lord, Your mercy is higher than the heavens, wider than the earth, deeper than the sea. There is no sin too great for Your forgiveness, no soul too lost for Your reach, no past too dark for Your light. The parable of the Prodigal Son reveals the heart of God — a Father who watches and waits, who runs to meet the returning sinner, who embraces and kisses and restores. I pray today for the grace to trust in Your mercy without limit. When the evil one tells me that my sins are too great, remind me that Your mercy is greater. When I am tempted to despair, remind me that You came to call sinners, not the just. When I feel unworthy, remind me that You are drawn to weakness and brokenness. O Jesus, mercy of God, I place my trust in the boundless ocean of Your divine mercy.`,
  },
  {
    id: "src-np-8",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 8 — Healing: The Restoration of the Soul",
    category: "novenas",
    day: 8,
    intention: "To experience the healing power of reconciliation",
    text: `O divine Healer, the Sacrament of Reconciliation is the hospital of the soul, where every wound is treated, every disease is cured, and every patient is restored to health. Sin wounds the soul in its deepest faculties — it darkens the intellect, weakens the will, disorders the emotions, and separates us from God. But confession heals all these wounds through the power of Your blood and the operation of Your grace. I pray today for the complete healing of my soul. Heal the wounds that I have inflicted upon myself through sin. Restore what has been damaged. Strengthen what has been weakened. Illuminate what has been darkened. Grant me the health of soul that enables me to love You with my whole heart, mind, and strength. O Jesus, physician of souls, heal me through the Sacrament of Your mercy.`,
  },
  {
    id: "src-np-9",
    novenaId: "novenas-sacrament-reconciliation",
    title: "Day 9 — Peace: The Gift of a Clear Conscience",
    category: "novenas",
    day: 9,
    intention: "To experience the peace that comes from reconciliation",
    text: `O Prince of Peace, You who said "My peace I give to you, not as the world gives" (John 14:27), I pray today for the peace that comes from a clean conscience and a forgiven soul. There is no peace like the peace that follows a good confession — the burden lifted, the guilt removed, the darkness replaced by light. This is the peace that the world cannot give because the world does not know how to heal the soul. I thank You for this inestimable gift. Help me to guard this peace by avoiding the occasions of sin, by living in a state of grace, and by returning to confession quickly whenever I fall. May the peace of Christ rule in my heart always, and may I be an instrument of Your peace to others. O Jesus, our peace and our reconciliation, I praise You for the gift of confession and the peace it brings to the soul.`,
  },

  // NOVENA TO THE SACRAMENT OF THE EUCHARIST
  // novenaId: "novenas-sacrament-eucharist"

  {
    id: "seu-np-1",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 1 — Real Presence: Jesus Body, Blood, Soul, and Divinity",
    category: "novenas",
    day: 1,
    intention: "To deepen belief in the Real Presence of Christ in the Eucharist",
    text: `O Jesus Christ, present in the Most Holy Sacrament of the Eucharist, I adore You today as truly, really, and substantially present — Body, Blood, Soul, and Divinity — under the appearances of bread and wine. This is the greatest of all mysteries, the "mystery of faith," the miracle that surpasses all other miracles. You, the Creator of the universe,隐藏 Your infinite majesty under the humble appearances of a little piece of bread. I pray today for an increase of faith in Your Real Presence. Help me to approach the Eucharist with the same reverence with which the angels approach Your throne. Banish from my heart all indifference, distraction, and lukewarmness in the presence of the Blessed Sacrament. O Jesus, hidden God, I believe, I adore, I hope, and I love You. May my faith in Your Real Presence grow ever deeper and stronger.`,
  },
  {
    id: "seu-np-2",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 2 — Last Supper: The Institution of the Eucharist",
    category: "novenas",
    day: 2,
    intention: "To contemplate the night Jesus gave us the Eucharist",
    text: `O Jesus, on the night before You suffered, You gathered Your Apostles in the Upper Room for the Passover meal. Taking bread, You blessed and broke it, saying "This is My Body, which will be given for you." Taking the cup of wine, You said "This is My Blood of the covenant, which will be poured out for many for the forgiveness of sins." In this supreme act of love, You gave the Church the greatest gift this side of heaven — Yourself, truly present in the Sacrament of the Eucharist. I pray today for the grace to approach the Holy Mass with the same awe and devotion with which the Apostles received You at the Last Supper. Help me to understand that every Mass is a re-presentation of Calvary, that the sacrifice of the cross is made present on every altar. O Jesus, Eucharistic Lord, I thank You for instituting this sacrament of incomprehensible love.`,
  },
  {
    id: "seu-np-3",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 3 — Transubstantiation: The Miracle of Change",
    category: "novenas",
    day: 3,
    intention: "To wonder at the mystery of transubstantiation",
    text: `O Almighty Jesus, at the words of consecration spoken by the priest, the substance of bread and wine is completely changed into Your Body and Blood, while the appearances of bread and wine remain. This is transubstantiation — the greatest miracle ever performed, for it is repeated at every Mass throughout the world. No greater power can be conceived than the power to change one substance into another, and this power You exercise through Your minister at every celebration of the Eucharist. I pray today for a deeper understanding of this ineffable mystery. While my intellect cannot fully comprehend how this change occurs, my faith embraces it with joy and my heart adores it with love. Help me never to reduce the Eucharist to a mere symbol or mere memorial, but to worship You as the living God truly present in this Sacrament. O Jesus, miracle of miracles, I worship You in the mystery of transubstantiation.`,
  },
  {
    id: "seu-np-4",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 4 — Holy Communion: Union with Christ",
    category: "novenas",
    day: 4,
    intention: "To receive Communion with reverence and devotion",
    text: `O Jesus, when I receive Holy Communion, I receive nothing less than You — Your Body, Your Blood, Your Soul, and Your Divinity. In this most intimate encounter, You unite Yourself to me and I to You. "He who eats My flesh and drinks My blood abides in Me, and I in him" (John 6:56). This is the closest union possible between Creator and creature on this earth. I pray today that I may approach Holy Communion with the reverence, preparation, and devotion it deserves. Help me to receive You worthily, with a clean soul and a loving heart. Assist me to make proper preparation before Communion and to offer worthy thanksgiving afterward. May the grace of Holy Communion transform my life, strengthen me against temptation, and draw me ever closer to You. O Jesus, food of angels, I receive You with love and gratitude.`,
  },
  {
    id: "seu-np-5",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 5 — Adoration: Before the Blessed Sacrament",
    category: "novenas",
    day: 5,
    intention: "To cultivate a love for Eucharistic adoration",
    text: `O hidden Jesus, You who remain with us in the Blessed Sacrament even after Mass has ended, who wait patiently in the tabernacle for souls to visit You, who expose YourSacred Heart to the world in Eucharistic adoration — I adore You today in this most Blessed Sacrament. How often You are left alone, forgotten in the tabernacle, while the world rushes by without a thought for Your loving presence! I pray today for the grace to visit You more frequently in adoration. Help me to sit at Your feet like Mary of Bethany, to pour out my heart before You in prayer, to listen for Your voice in the silence of Eucharistic contemplation. Grant me the faith to believe that You are truly present, the love to remain with You, and the devotion to adore You with deep reverence. O Jesus, Eucharistic King, I adore You now and forever.`,
  },
  {
    id: "seu-np-6",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 6 — Sacrifice: The Unbloody Re-presentation of Calvary",
    category: "novenas",
    day: 6,
    intention: "To understand and participate in the sacrificial nature of the Mass",
    text: `O Jesus, High Priest and Victim, every Holy Mass is a true sacrifice — not a new sacrifice, but the same sacrifice of Calvary made present in an unbloody manner upon the altar. The priest acts in Your person, the words of consecration effect the change, and the faithful are invited to unite their sacrifices with Yours. I pray today for a deeper understanding of the sacrificial nature of the Mass. Help me to offer my Mass not as a spectator but as a participant, uniting my prayers, my sufferings, and my daily Cross with Your perfect sacrifice on the cross. Grant me the grace to understand that the Mass is not merely a meal but a sacrifice — the same sacrifice that redeemed the world. O Jesus, Lamb of God, who offered Yourself for our salvation, I unite my sacrifice to Yours in every Mass.`,
  },
  {
    id: "seu-np-7",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 7 — Thanksgiving: The Oblation of Grateful Love",
    category: "novenas",
    day: 7,
    intention: "To offer thanksgiving for the gift of the Eucharist",
    text: `O generous Jesus, what thanks can I possibly offer You for the gift of the Holy Eucharist? You who are infinite, eternal, and infinitely blessed — You give Yourself to me, finite, mortal, and sinful, as food for my soul. The gratitude I feel is inadequate, yet I offer it to You with all my heart. I thank You for the Real Presence, for the grace of Communion, for the privilege of adoration, for the sacrifice of the Mass, for the priestly ministry that makes this sacrament possible. Help me to live each day as a Eucharistic life — to give thanks in all circumstances, to offer myself to the Father with You in every Mass, to live with the generosity and self-gift that the Eucharist teaches. O Jesus, Eucharistic sacrifice of thanksgiving, accept my poor offering of gratitude and make it pleasing to the Father.`,
  },
  {
    id: "seu-np-8",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 8 — Unity: One Bread, One Body",
    category: "novenas",
    day: 8,
    intention: "To foster unity among the members of Christ's Body",
    text: `O Jesus, You said "The bread that I will give is My flesh for the life of the world" (John 6:51). In giving us the Eucharist, You give us not only Yourself but also one another, for "because there is one bread, we who are many are one body, for we all partake of the one bread" (1 Corinthians 10:17). The Eucharist is the sacrament of unity, binding the faithful together into the one Body of Christ. I pray today for unity in the Church, unity in my parish, unity in my family. Help me to love the members of Christ's Body as I love Christ Himself, for to receive Him in Communion and then to hate my brother or sister is a contradiction of the deepest kind. Grant me the grace to work for reconciliation, to heal divisions, to build bridges of charity. O Jesus, our Eucharistic unity, make us all one in You.`,
  },
  {
    id: "seu-np-9",
    novenaId: "novenas-sacrament-eucharist",
    title: "Day 9 — Heaven: The Foretaste of Eternal Glory",
    category: "novenas",
    day: 9,
    intention: "To live in anticipation of the heavenly banquet",
    text: `O Jesus, Eucharistic Lord, the Holy Eucharist is called the "viaticum" — the food for the journey — and also the "pledge of future glory." In receiving Your Body and Blood, I receive a foretaste of the heavenly banquet, a preview of the eternal joy that awaits the faithful in heaven. The Eucharist connects earth to heaven, time to eternity, the pilgrim Church to the Church triumphant. I pray today for the grace to live with heaven always before my eyes, strengthened by the Eucharist on my journey. Help me to remember that the joy of the Eucharist is but a small taste of the infinite bliss that awaits those who love God. When the trials of life weigh me down, lift my eyes to the heavenly vision. When I receive You in Communion, let me anticipate the day when I will see You face to face. O Jesus, bread of heaven, nourish my soul for the eternal life that awaits.`,
  },

  // NOVENA TO THE HOLY CROSS AND THE PASSION
  // novenaId: "novenas-holy-cross-passion"

  {
    id: "shc-np-1",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 1 — The Tree: The Instrument of Salvation",
    category: "novenas",
    day: 1,
    intention: "To honor the Holy Cross as the instrument of redemption",
    text: `O Holy Cross of Christ, sacred wood upon which the Savior of the world offered the perfect sacrifice for the sins of humanity, I venerate you today as the most precious relic of the Christian faith. You were once a tree in the forest, then a beam of wood in the workshop, then an instrument of torture in the hands of the executioner — but God transformed you into the throne of glory, the altar of the New Covenant, the bridge between heaven and earth. I pray today for a deeper love of the Cross of Christ. Help me to understand that the Cross is not merely an object of devotion but the very means by which salvation was won for the human race. May I glory in the Cross of our Lord Jesus Christ, through whom the world has been crucified to me and I to the world. O Holy Cross, tree of life, I honor you as the instrument of my redemption.`,
  },
  {
    id: "shc-np-2",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 2 — Suffering: The Passion of Christ",
    category: "novenas",
    day: 2,
    intention: "To contemplate the sufferings of Christ on the Cross",
    text: `O suffering Jesus, Lamb of God, I contemplate today the infinite sorrows of Your Passion. From the bloody sweat in Gethsemane to the cruel scourging at the pillar, from the crowning with thorns to the mocking and buffeting, from the way of the cross to the nailing of Your hands and feet, from the lifting up of the cross to the final breath — Your suffering was beyond all human comprehension. You endured not merely physical agony but the spiritual agony of bearing the sins of all humanity. You who are innocence itself suffered the penalty of guilt. You who are Life itself tasted death. I pray today that Your Passion may not be wasted in my life. Help me to unite my small sufferings with Your great suffering, and to find in the Cross the meaning and redemption of all pain. O Jesus, Lamb of God, I gaze upon Your suffering with sorrow and love.`,
  },
  {
    id: "shc-np-3",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 3 — Redemption: The Price of Our Salvation",
    category: "novenas",
    day: 3,
    intention: "To appreciate the infinite value of Christ's redemptive sacrifice",
    text: `O Redeemer Jesus, on the Cross You accomplished the work of our redemption. By the infinite value of Your precious blood, You ransomed us from the slavery of sin, reconciled us with the Father, and opened the gates of heaven. No mere creature could have offered this sacrifice — only the Son of God made man could pay the debt of Adam's sin and restore the communion between God and humanity. I pray today with a grateful heart for the redemption You have won for me. Help me to live in a manner worthy of the price that was paid for my soul. May I never take for granted the infinite gift of salvation, but cooperate with Your grace daily. O Jesus, Redeemer of the human race, I thank You for the redemption won on the Cross.`,
  },
  {
    id: "shc-np-4",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 4 — Love: The Love of the Cross",
    category: "novenas",
    day: 4,
    intention: "To be moved by the love that nailed Christ to the Cross",
    text: `O loving Jesus, what greater love could there be than this — that You, the sinless Son of God, died for sinners? You were not compelled to go to the Cross; You went freely, in perfect freedom and perfect love. "No one takes my life from me; I lay it down of my own accord" (John 10:18). You loved me before I existed, You loved me while I was still in sin, You loved me to the point of death, even death on a cross. I pray today that the love of the Cross may penetrate my heart more deeply. Help me to understand that I am loved beyond all measure, that I am worth the blood of Christ, that there is no depth to which God's love will not descend for my sake. Transform me by this love, that I may love others as You have loved me. O Jesus, love of my soul, nail my heart to Your sacred heart.`,
  },
  {
    id: "shc-np-5",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 5 — Forgiveness: Father, Forgive Them",
    category: "novenas",
    day: 5,
    intention: "To forgive as Christ forgave from the Cross",
    text: `O forgiving Jesus, from the height of the Cross You prayed for Your executioners: "Father, forgive them, for they know not what they do." In the very act of being murdered, You forgave Your murderers. You did not curse them but blessed them, did not condemn them but interceded for them. This is the forgiveness that redeems, the mercy that conquers evil, the love that is stronger than death. I pray today for the grace to forgive as You forgave. Help me to release every grudge, every resentment, every desire for revenge that poisons my soul. Grant me the supernatural strength to pray for those who have wronged me, to bless those who have cursed me, to love those who have hated me. O Jesus, model of forgiveness, write the words "Father, forgive them" upon my heart.`,
  },
  {
    id: "shc-np-6",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 6 — The Way: Carrying Our Cross Daily",
    category: "novenas",
    day: 6,
    intention: "To take up my cross and follow Christ every day",
    text: `O crucified Jesus, You said: "If anyone would come after me, let him deny himself and take up his cross daily and follow me" (Luke 9:23). The Christian life is not a journey of ease and comfort but a way of the cross. Every day brings its crosses — small ones and great ones — and You call me to carry them in Your footsteps. I pray today for the grace to accept my daily crosses with patience and love. Help me not to flee from suffering but to embrace it as a participation in Your Passion. When I am tempted to complain, remind me of Your silence before your accusers. When I am tempted to despair, remind me of Your trust on the cross. When I am tempted to self-pity, remind me that You bore the sins of the whole world. O Jesus, way of the cross, teach me to follow You faithfully on the path of sacrifice.`,
  },
  {
    id: "shc-np-7",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 7 — Victory: The Cross Triumphant",
    category: "novenas",
    day: 7,
    intention: "To proclaim the victory of the Cross over sin and evil",
    text: `O victorious Christ, the Cross that was once an instrument of shame and death has become the symbol of triumph and glory. By the Cross, You conquered Satan, sin, and death. By the Cross, the power of darkness was shattered and the Kingdom of God was established. The sign of the Cross, made by the faithful, is a sacramental that puts the demons to flight and claims the protection of heaven. I pray today with confidence in the victory of the Cross. Help me to wear the sign of the Cross proudly, to live by its power, and to trust in its protection. May I never be ashamed of the Cross, for it is the power of God for salvation. In every trial, may I remember that the Cross always leads to resurrection. O Jesus, triumphant on the Cross, I celebrate Your victory over all the powers of evil.`,
  },
  {
    id: "shc-np-8",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 8 — Glory: The Cross Made Glorious",
    category: "novenas",
    day: 8,
    intention: "To see the glory hidden in the mystery of the Cross",
    text: `O glorified Jesus, when You were raised upon the Cross, You were lifted up in glory — not the glory of worldly power but the glory of divine love revealed in sacrifice. The Cross is not merely the instrument of suffering but the throne from which You reign as King. The rays of the cross spread light to all the world. The wood that bore the Savior now bears the Savior's glory. I pray today for eyes of faith to see the glory hidden in the mystery of the Cross. Help me to understand that suffering united to Christ is not wasted but glorified, that the cross is not the end but the beginning, that death leads to resurrection. May I see Your glory in the Eucharist, in the saints, in the Church, and in every act of love and sacrifice. O Jesus, glorious King of the Cross, I worship You in Your crucified glory.`,
  },
  {
    id: "shc-np-9",
    novenaId: "novenas-holy-cross-passion",
    title: "Day 9 — Consecration: Total Dedication to the Cross",
    category: "novenas",
    day: 9,
    intention: "To consecrate my life entirely to Christ crucified",
    text: `O crucified Lord Jesus Christ, as this novena draws to a close, I desire to consecrate myself entirely to You and to Your Holy Cross. I give You my mind, to think Your thoughts. I give You my heart, to love what You love. I give You my will, to do what You will. I give You my hands, to labor for Your kingdom. I give You my feet, to walk in Your footsteps. I give You my sufferings, to unite them with Your Passion. I give You my joys, to offer them back to You in gratitude. I give You my entire life, to spend it for Your glory and the salvation of souls. O Holy Cross, be my guide, my comfort, my hope, and my glory. O Jesus crucified, be my all in all. May I live and die with the words on my lips: "I am crucified with Christ, yet I live; no longer I, but Christ lives in me."`,
  },
];
